from typing import TypedDict, List, Dict, Any, Optional

from app.core.config import settings


class CritiqueResult(TypedDict, total=False):
    """Structured evaluation generated by the critic node."""
    is_valid: bool
    feedback: str
    hallucination_score: float
    suggested_queries: List[str]


class AgentWorkflowState(TypedDict, total=False):
    """
    Enterprise LangGraph Workflow State tracking the multi-agent reasoning loop.
    Planner -> Researcher -> Synthesizer -> Critic (-> Planner on rejected drafts).
    """
    task_id: str
    tenant_id: str
    user_prompt: str
    trace_id: str
    document_ids: List[str]
    metadata: Dict[str, Any]
    plan: List[str]
    research_data: List[Dict[str, Any]]
    draft_report: str
    critique: Dict[str, Any]
    iteration_count: int
    current_node: str
    status: str
    error: Optional[str]
    # Non-fatal retrieval / tool / LLM errors surfaced to callers instead of being swallowed
    errors: List[str]
    # Cumulative LLM token usage reported by the provider (0 in deterministic mode)
    token_usage: int
    # "llm" when an LLM is configured, "deterministic" otherwise
    llm_mode: str


def build_initial_state(
    task_id: str,
    tenant_id: str,
    user_prompt: str,
    trace_id: str,
    document_ids: Optional[List[str]] = None,
    metadata: Optional[Dict[str, Any]] = None,
) -> AgentWorkflowState:
    """Creates a fully-populated initial workflow state."""
    return {
        "task_id": task_id,
        "tenant_id": tenant_id,
        "user_prompt": user_prompt,
        "trace_id": trace_id,
        "document_ids": [str(d) for d in (document_ids or [])],
        "metadata": dict(metadata or {}),
        "plan": [],
        "research_data": [],
        "draft_report": "",
        "critique": {},
        "iteration_count": 0,
        "current_node": "START",
        "status": "PROCESSING",
        "errors": [],
        "token_usage": 0,
        "llm_mode": "llm" if settings.llm_enabled else "deterministic",
    }
